<?php
/**
 * Database connection (PDO / MySQL).
 *
 * Credentials come from config/database.php (created from
 * config/database.example.php, or generated by install.php), and can be
 * overridden with LIBMEN_DB_* environment variables.
 */

function db_config(): array {
    $path = __DIR__ . '/../config/database.php';
    if (is_file($path)) {
        $cfg = require $path;
        if (is_array($cfg)) return $cfg;
    }
    // Fall back to the example template so the app fails with a clear,
    // actionable message instead of a fatal error.
    return require __DIR__ . '/../config/database.example.php';
}

/** Try to connect; throws PDOException on failure (used by install.php). */
function db_try(?array $cfg = null): PDO {
    $cfg = $cfg ?? db_config();
    $dsn = sprintf(
        'mysql:host=%s;port=%s;dbname=%s;charset=utf8mb4',
        $cfg['host'], $cfg['port'], $cfg['name']
    );
    return new PDO($dsn, $cfg['user'], $cfg['pass'], [
        PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        PDO::ATTR_EMULATE_PREPARES   => false,
    ]);
}

function db(): PDO {
    static $pdo = null;
    if ($pdo instanceof PDO) return $pdo;

    try {
        $pdo = db_try();
    } catch (PDOException $e) {
        http_response_code(500);
        exit(
            '<div style="font-family:sans-serif;max-width:640px;margin:60px auto;padding:24px;' .
            'border:1px solid #e5b4b4;background:#fff5f5;border-radius:12px;color:#7f1d1d">' .
            '<h2 style="margin-top:0">Database connection failed</h2>' .
            '<p>The application could not connect to the MySQL database. On InfinityFree this ' .
            'usually means the credentials in <code>config/database.php</code> do not match the ' .
            'database created in hPanel &rarr; MySQL Databases.</p>' .
            '<p>Fix it by editing <code>config/database.php</code>, or open <code>/install.php</code> ' .
            'to set the credentials and create the tables in one step.</p>' .
            '<p style="color:#9f1239"><small>' . htmlspecialchars($e->getMessage(), ENT_QUOTES) . '</small></p>' .
            '</div>'
        );
    }
    return $pdo;
}
